ALLOWED_PRIMARY_CATEGORIES = {
    "filesystem",
    "serialization",
    "artifact",
    "env_config",
    "network",
    "external_platform",
    "subprocess",
    "time",
    "unknown",
}

EXPECTED_IO_CASE_COUNT = 25


def _runtime_text(case: dict[str, object]) -> str:
    path = REPO_ROOT / str(case["runtime_file"])
    assert path.exists(), f"runtime file missing: {path}"
    return path.read_text(encoding="utf-8")


def test_a8_r40_io_boundary_plan_shape() -> None:
    assert len(IO_BOUNDARY_CASES) == EXPECTED_IO_CASE_COUNT

    ids = [case["test_id"] for case in IO_BOUNDARY_CASES]
    assert len(ids) == len(set(ids))
    assert all(str(test_id).startswith("A8R40_IO_") for test_id in ids)

    assert all(case["mutation_allowed"] == 0 for case in IO_BOUNDARY_CASES)
    assert all(case["runtime_patch_allowed"] == 0 for case in IO_BOUNDARY_CASES)


@pytest.mark.parametrize("case", IO_BOUNDARY_CASES, ids=lambda case: case["test_id"])
def test_a8_r40_io_boundary_runtime_symbol_is_present(case: dict[str, object]) -> None:
    text = _runtime_text(case)
    assert str(case["symbol"]) in text


@pytest.mark.parametrize("case", IO_BOUNDARY_CASES, ids=lambda case: case["test_id"])
def test_a8_r40_io_boundary_case_has_fixture_and_assertion_strategy(case: dict[str, object]) -> None:
    assert str(case["primary_category"]) in ALLOWED_PRIMARY_CATEGORIES
    assert str(case["fixture_strategy"]).strip()
    assert str(case["assertion_strategy"]).strip()
    assert str(case["runtime_file"]).strip()
    assert str(case["kind"]) in {"class", "function"}


@pytest.mark.parametrize("case", IO_BOUNDARY_CASES, ids=lambda case: case["test_id"])
def test_a8_r40_io_boundary_case_keeps_runtime_patch_blocked(case: dict[str, object]) -> None:
    assert case["mutation_allowed"] == 0
    assert case["runtime_patch_allowed"] == 0
